<?php $title='Partnerships built on clear purpose.'; $eyebrow='Work & Impact'; $intro='SkillsPark welcomes local and international collaboration in training, technology, education and institutional improvement.'; $breadcrumbs=[['label'=>'Home','url'=>'/'],['label'=>'Work & Impact','url'=>'/work'],['label'=>'Partnerships','url'=>'/work/partnerships']]; require ROOT_PATH . '/app/views/components/page-hero.php'; $partners=published(content('partners')); ?>
